import { useState } from 'react'
import { useImagePicker } from './useImagePicker'
import { useCreateAssetMutation } from '@/generated/graphql'

type UploadAssetParams = {
	projectGroupId: string
}

export function useUploadAsset() {
	const { pickAndUploadImage, isUploading: isPickingOrUploading } =
		useImagePicker()
	const [createAsset] = useCreateAssetMutation()
	const [isCreating, setIsCreating] = useState(false)

	const uploadAsset = async ({ projectGroupId }: UploadAssetParams) => {
		try {
			setIsCreating(true)

			const result = await pickAndUploadImage()
			if (!result || !result.uploadcareUuid || !result.uploadcareUrl) {
				return { success: false as const }
			}

			await createAsset({
				variables: {
					input: {
						externalId: result.uploadcareUuid,
						fileName: result.filename || 'image',
						mimeType: result.mimeType || 'image/jpeg',
						projectGroupId,
						url: result.uploadcareUrl
					}
				}
			})

			return { success: true as const }
		} catch (error) {
			console.error('useUploadAsset error:', error)
			return { success: false as const, error }
		} finally {
			setIsCreating(false)
		}
	}

	return {
		uploadAsset,
		isUploading: isPickingOrUploading || isCreating
	}
}
